package main

import (
	"bufio"
	"fmt"
	"os"
)

func isUndoubtedlyLucky(x int) bool {
	if x == 0 {
		return false
	}
	digits := make(map[int]struct{})
	for x > 0 {
		d := x % 10
		digits[d] = struct{}{}
		if len(digits) > 2 {
			return false
		}
		x /= 10
	}
	return true
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var n int
	fmt.Fscan(in, &n)

	count := 0
	for i := 1; i <= n; i++ {
		if isUndoubtedlyLucky(i) {
			count++
		}
	}
	fmt.Println(count)
}

