	digits := make([]int, 0, 10)
	for x := a; x > 0; x /= 10 {
		digits = append(digits, int(x%10))
	}

	// Try all pairs (x, y)
	for x := 0; x <= 9; x++ {
		for y := 0; y <= 9; y++ {
			ok := true
